SELECT CAST(SUM(CASE WHEN T2.remaining < 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.event_id) AS percentage_over_budget
FROM event AS T1
JOIN budget AS T2 ON T1.event_id = T2.link_to_event;

SELECT COUNT(*) 
FROM schools 
WHERE County = 'Alpine' AND StatusType IN ('Active', 'Closed') AND EdOpsName = 'District Community Day School';

SELECT AVG(height_cm) AS average_height
FROM superhero
WHERE alignment_id = (SELECT id FROM alignment WHERE alignment = 'Neutral');

SELECT COUNT(*) AS WellFinishedPosts
FROM posts
WHERE ClosedDate IS NULL AND UserId = 23853 AND CreationDate = '2013-07-12 09:08:18.0';

SELECT MIN(LowGrade) AS LowestGrade
FROM frpm
WHERE EdOpsCode = 'SPECON' AND District = '0613360';

SELECT SUM(CASE WHEN T1.A3 = 'East Bohemia' THEN T1.A16 ELSE 0 END) - SUM(CASE WHEN T1.A3 = 'North Bohemia' THEN T1.A16 ELSE 0 END) AS diff
FROM district AS T1
WHERE T1.A2 = '1996';

SELECT Diagnosis FROM Patient WHERE ID IN (
    SELECT ID FROM Laboratory WHERE TG < 200 ORDER BY TG DESC LIMIT 1
)

SELECT CAST(SUM(CASE WHEN T2.publisher_name = 'Marvel Comics' AND T1.alignment = 'Good' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T2.publisher_name) AS percentage
FROM superhero AS T1
JOIN publisher AS T2 ON T1.publisher_id = T2.id;
